-- Banner 管理页面。可重复执行，不授予角色。
BEGIN;
SET @mall_root=(SELECT menu_id FROM sys_menu WHERE parent_id=0 AND path='mall' AND menu_type='M' ORDER BY menu_id LIMIT 1);
SET @promotion_root=(SELECT menu_id FROM sys_menu WHERE parent_id=@mall_root AND path='promotion' AND menu_type='M' ORDER BY menu_id LIMIT 1);
SET @banner=(SELECT menu_id FROM sys_menu WHERE parent_id=@promotion_root AND path='banner' AND menu_type='C' ORDER BY menu_id LIMIT 1);
COMMIT;
